    {
      "product": "Alvik",
      "file": "docling_chunks.jsonl",
      "text": "[Product: Alvik] [Product category: Education] [Element of Alvik: None] [Tutorial about Alvik: None] \n\n3.2 Getting Started - Arduino IDE\nIf you want to program your Alvik robot while offline you need to install the Arduino® Desktop IDE [2] . To connect the Alvik robot to your computer, you will need a USB-C® cable.",
      "product_category": "Education",
      "chunk_id": "Alvik-datasheet::c20"
