    {
      "product": "Nano Matter",
      "file": "docling_chunks.jsonl",
      "text": "[Product: Nano Matter] [Product category: Nano Family] [Element of Nano Matter: None] [Tutorial about Nano Matter: Tutorial_Nano Matter] \n\nRGB light overview Thanks to the seamless compatibilit of the Nano Matter with almost any Matter network we can easily integrate our RGB light with Amazon Alexa, Google Assistant, Apple Home Home Assistant and even any professional custom solution. We have prepared a short demo in video format in case you are a visual learner.",
      "product_category": "Nano Family",
      "chunk_id": "Tutorial_Nano Matter_RGB_Light::c1"
    },
